import SuperJSON from './index.js';
import { processStackString, processStackFrames } from './error-stack.js';
import { sanitizeMessage } from './error-sanitizer.js';

simpleTransformation(
  isError,
  'Error',
  (v, superJson) => {
    const baseError: any = {
      name: v.name,
      message: v.message,
    };

    if ('cause' in v) {
      baseError.cause = v.cause;
    }

    superJson.allowedErrorProps.forEach(prop => {
      baseError[prop] = (v as any)[prop];
    });

    return baseError;
  },
  (v, superJson) => {
    const e = new Error(v.message, { cause: v.cause });
    e.name = v.name;
    e.stack = v.stack;

    superJson.allowedErrorProps.forEach(prop => {
      (e as any)[prop] = v[prop];
    });

    return e;
  }
),

function errorMode(error: Error, superJson: SuperJSON): 'off' | 'string' | 'frames' {
  const options = superJson.errorStack;
  return options && (!options.classFilter.length || options.classFilter.includes(error.name))
    ? options.mode : 'off';
}

function serializeError(error: Error, superJson: SuperJSON): any {
  const options = superJson.errorStack;
  if (!options) {
    const result: any = { name: error.name, message: error.message };
    if ('cause' in error) result.cause = error.cause;
    superJson.allowedErrorProps.forEach(prop => { result[prop] = (error as any)[prop]; });
    return superJson.errorClassRegistry.getProcessor(error.name)?.(result) ?? result;
  }
  const seen = new Set<Error>();
  const serialize = (value: Error, depth: number): any => {
    seen.add(value);
    const matches = !options.classFilter.length || options.classFilter.includes(value.name);
    const result: any = { name: value.name, message: matches && options.sanitizeMessage ? sanitizeMessage(value.message) : value.message };
    superJson.allowedErrorProps.forEach(prop => {
      if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause' && prop !== 'errors' && prop !== 'name' && prop !== 'message') result[prop] = (value as any)[prop];
    });
    const mode = errorMode(value, superJson);
    if (mode === 'string' && superJson.allowedErrorProps.includes('stack') && typeof value.stack === 'string') result.stack = processStackString(value.stack, options);
    if (mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames') && typeof value.stack === 'string') result.stackFrames = processStackFrames(value.stack, options);
    if (value instanceof AggregateError) result.errors = value.errors;
    const cause = value.cause;
    const limit = options.includeCauses === 'direct' ? 1 : options.includeCauses === 'deep' ? options.maxCauseDepth : 0;
    if (depth < limit && cause instanceof Error && !seen.has(cause)) result.cause = serialize(cause, depth + 1);
    return superJson.errorClassRegistry.getProcessor(value.name)?.(result) ?? result;
  };
  return serialize(error, 0);
}

function deserializeError(value: any, superJson: SuperJSON): Error {
  const restore = (v: any): Error => {
    const cause = v.cause && !(v.cause instanceof Error) && typeof v.cause === 'object' && typeof v.cause.name === 'string' ? restore(v.cause) : v.cause;
    const e: Error = Array.isArray(v.errors) ? new AggregateError(v.errors, v.message, { cause }) : new Error(v.message, { cause });
    e.name = v.name;
    e.stack = v.stack;
    if (Array.isArray(v.stackFrames)) {
      (e as any).stackFrames = v.stackFrames;
      e.stack = v.stackFrames.map((frame: { raw: string }) => frame.raw).join('\n');
    }
    superJson.allowedErrorProps.forEach(prop => {
      if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause') (e as any)[prop] = v[prop];
      else if (prop === 'stack' && 'stack' in v) e.stack = v.stack;
    });
    return e;
  };
  return restore(value);
}

const errorRules = (['string', 'frames', 'off'] as const).map(mode =>
  simpleTransformation(
    (v, superJson): v is Error => isError(v) && errorMode(v, superJson) === mode,
    mode === 'string' ? 'Error/stack' : mode === 'frames' ? 'Error/frames' : 'Error',
    serializeError,
    deserializeError
  )
);

